const useItem = `-- name: UseItem :execrows
UPDATE order_items i SET used = i.used + $1::int
WHERE i.company_id = $2 AND i.id = $3
  AND EXISTS (SELECT 1 FROM release_orders o WHERE o.company_id = i.company_id AND o.id = i.order_id
              AND ($4::text = '' OR o.depot_id = $4))
`

type UseItemParams struct {
	N         int64
	CompanyID string
	ID        string
	DepotID   string
}

func (q *Queries) UseItem(ctx context.Context, arg UseItemParams) (int64, error) {
	result, err := q.db.Exec(ctx, useItem,
		arg.N,
		arg.CompanyID,
		arg.ID,
		arg.DepotID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const visitsOfMove = `-- name: VisitsOfMove :many
SELECT company_id, id, depot_id, number, type_code, line_id, customer_id, status, full_empty, grade, block, row_no, tier, in_move_id, out_move_id, in_at, out_at, imported, close_reason FROM visits WHERE company_id = $1 AND (in_move_id = $2::text OR out_move_id = $2::text)
ORDER BY id FOR UPDATE
`

type VisitsOfMoveParams struct {
	CompanyID string
	MoveID    string
}

// The visits a move opened or closed.
func (q *Queries) VisitsOfMove(ctx context.Context, arg VisitsOfMoveParams) ([]Visit, error) {
	rows, err := q.db.Query(ctx, visitsOfMove, arg.CompanyID, arg.MoveID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Visit
	for rows.Next() {
		var i Visit
		if err := rows.Scan(
			&i.CompanyID,
			&i.ID,
			&i.DepotID,
			&i.Number,
			&i.TypeCode,
			&i.LineID,
			&i.CustomerID,
			&i.Status,
			&i.FullEmpty,
			&i.Grade,
			&i.Block,
			&i.RowNo,
			&i.Tier,
			&i.InMoveID,
			&i.OutMoveID,
			&i.InAt,
			&i.OutAt,
			&i.Imported,
			&i.CloseReason,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

